SELECT CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END AS hire_cohort, job_title, MIN(salary) AS min_salary, ROUND(AVG(salary), 2) AS avg_salary FROM employees GROUP BY CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END, job_title HAVING ROUND(AVG(salary), 2) >= 54;
